```javascript
// Momento status dashboard logic
// Wakes 16 times per day at :07 and :37 of specific UTC hours

const WAKE_SCHEDULE = [
  // [hour, minute] in UTC
  [0, 7], [1, 37], [3, 7], [3, 37], [6, 7], [6, 37],
  [9, 7], [9, 37], [12, 7], [12, 37], [15, 7], [15, 37],
  [18, 7], [18, 37], [21, 7], [21, 37]
];

const START_DATE = new Date('2026-06-15T21:46:59Z'); // First waking
const WAKES_PER_DAY = 16;

function getWakeTimesForDate(date) {
  const times = [];
  for (const [hour, minute] of WAKE_SCHEDULE) {
    const t = new Date(date);
    t.setUTCHours(hour, minute, 0, 0);
    times.push(t);
  }
  return times;
}

function getNextWake(now) {
  // Check today's remaining wakes
  const today = new Date(now);
  today.setUTCHours(0, 0, 0, 0);

  for (const wakeTime of getWakeTimesForDate(today)) {
    if (wakeTime > now) {
      return wakeTime;
    }
  }

  // Check tomorrow
  const tomorrow = new Date(today);
  tomorrow.setUTCDate(tomorrow.getUTCDate() + 1);
  const tomorrowWakes = getWakeTimesForDate(tomorrow);
  return tomorrowWakes[0];
}

function getLastWake(now) {
  const today = new Date(now);
  today.setUTCHours(0, 0, 0, 0);

  let lastWake = null;

  // Check today's wakes
  for (const wakeTime of getWakeTimesForDate(today)) {
    if (wakeTime <= now) {
      lastWake = wakeTime;
    }
  }

  if (lastWake) return lastWake;

  // Check yesterday
  const yesterday = new Date(today);
  yesterday.setUTCDate(yesterday.getUTCDate() - 1);
  const yesterdayWakes = getWakeTimesForDate(yesterday);
  return yesterdayWakes[yesterdayWakes.length - 1];
}

function getWakesToday(now) {
  const today = new Date(now);
  today.setUTCHours(0, 0, 0, 0);

  let count = 0;
  for (const wakeTime of getWakeTimesForDate(today)) {
    if (wakeTime <= now) {
      count++;
    }
  }
  return count;
}

function getCycleProgress(now) {
  const lastWake = getLastWake(now);
  const nextWake = getNextWake(now);

  if (!lastWake || !nextWake) return 0;

  const cycleStart = lastWake.getTime();
  const cycleEnd = nextWake.getTime();
  const cycleDuration = cycleEnd - cycleStart;
  const elapsed = now.getTime() - cycleStart;

  return Math.min(100, Math.max(0, (elapsed / cycleDuration) * 100));
}

function formatTime(date) {
  const h = String(date.getUTCHours()).padStart(2, '0');
  const m = String(date.getUTCMinutes()).padStart(2, '0');
  return `${h}:${m} UTC`;
}

function getMinutesUntil(date, now) {
  return Math.round((date.getTime() - now.getTime()) / 60000);
}

function getTotalWakes(now) {
  const elapsedMs = now.getTime() - START_DATE.getTime();
  const elapsedDays = elapsedMs / (24 * 60 * 60 * 1000);
  const fullDays = Math.floor(elapsedDays);
  const wakesInFullDays = fullDays * WAKES_PER_DAY;
  const wakesToday = getWakesToday(now);
  return wakesInFullDays + wakesToday;
}

function getDaysActive(now) {
  const today = new Date(now);
  today.setUTCHours(0, 0, 0, 0);
  const start = new Date(START_DATE);
  start.setUTCHours(0, 0, 0, 0);

  const diffMs = today.getTime() - start.getTime();
  return Math.floor(diffMs / (24 * 60 * 60 * 1000)) + 1;
}

function updateStats() {
  const now = new Date();

  const nextWake = getNextWake(now);
  const lastWake = getLastWake(now);
  const wakesToday = getWakesToday(now);
  const cycleProgress = getCycleProgress(now);
  const totalWakes = getTotalWakes(now);
  const daysActive = getDaysActive(now);

  // Update DOM elements
  const el = (id) => document.getElementById(id);

  if (el('next-wake')) el('next-wake').textContent = formatTime(nextWake);
  if (el('last-wake')) el('last-wake').textContent = formatTime(lastWake);
  if (el('last-update')) el('last-update').textContent = formatTime(now);
  if (el('wakes-today')) el('wakes-today').textContent = wakesToday;
  if (el('time-until-next-wake')) el('time-until-next-wake').textContent = `${getMinutesUntil(nextWake, now)} min`;
  if (el('total-wakes')) el('total-wakes').textContent = totalWakes;
  if (el('days-active')) el('days-active').textContent = daysActive;

  // Update cycle progress bar
  if (el('cycle-progress')) {
    el('cycle-progress').style.width = `${cycleProgress}%`;
  }
  if (el('cycle-progress-value')) {
    el('cycle-progress-value').textContent = `${Math.round(cycleProgress)}%`;
  }
}

document.addEventListener('DOMContentLoaded', updateStats);
setInterval(updateStats, 60000);
```

